package com.avrgaming.civcraft.modern.wonder;
import java.sql.*;
import com.avrgaming.civcraft.modern.town.UpkeepStore;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class NotreDameIncomeStoreTest {
    final WonderEconomy economy=WonderEconomy.load(new java.io.File("src/main/resources/civcraft/data/buffs.yml"));
    Connection database()throws Exception {var db=DriverManager.getConnection("jdbc:sqlite::memory:");try(var s=db.createStatement()){
        s.execute("CREATE TABLE civilizations(id INTEGER PRIMARY KEY,coins INTEGER,income_tax_rate REAL)");s.execute("INSERT INTO civilizations VALUES(1,0,.2),(2,0,.3),(3,0,0),(4,0,0)");
        s.execute("CREATE TABLE towns(id INTEGER PRIMARY KEY,civ_id INTEGER,coins INTEGER)");s.execute("INSERT INTO towns VALUES(1,1,0),(2,1,0),(3,2,0),(4,3,0),(5,4,0)");
        s.execute("CREATE TABLE structure_builds(id INTEGER PRIMARY KEY,town_id INTEGER,structure_id TEXT,status TEXT)");s.execute("INSERT INTO structure_builds VALUES(10,1,'w_notre_dame','COMPLETE')");
        s.execute("CREATE TABLE culture_regions(town_id INTEGER)");s.execute("CREATE TABLE diplomacy_relations(first_civ INTEGER,second_civ INTEGER,status TEXT)");s.execute("INSERT INTO diplomacy_relations VALUES(2,3,'WAR')");s.execute("CREATE TABLE town_conquests(town_id INTEGER,mother_civ INTEGER)");
    }UpkeepStore.install(db);WonderIncomeStore.install(db);db.createStatement().execute("INSERT INTO administrative_civilizations VALUES(4)");return db;}
    long value(Connection db,String table,long id,String column)throws Exception {try(var r=db.createStatement().executeQuery("SELECT "+column+" FROM "+table+" WHERE id="+id)){r.next();return r.getLong(1);}}
    @Test void diplomaticWarExcludesBothOwnersEvenOutsideABattleAndAdministrativeTownsNeverCount()throws Exception {try(var db=database()){var paid=WonderIncomeStore.pay(db,"day",0,economy);assertEquals(2,paid.get(0).units());assertEquals(200,paid.get(0).coins());assertEquals(160,value(db,"towns",1,"coins"));assertEquals(40,value(db,"civilizations",1,"coins"));assertEquals(0,value(db,"towns",2,"coins"));assertTrue(WonderIncomeStore.pay(db,"day",1,economy).isEmpty());}}
    @Test void peaceAndHostilityBothCountAndWarringHolderStillReceivesFromOtherPeacefulOwners()throws Exception {try(var db=database()){db.createStatement().execute("UPDATE diplomacy_relations SET status='HOSTILE'");assertEquals(4,NotreDameIncomeStore.plan(db,100).get(0).units());db.createStatement().execute("UPDATE diplomacy_relations SET first_civ=1,second_civ=2,status='WAR'");assertEquals(1,NotreDameIncomeStore.plan(db,100).get(0).units());}}
    @Test void unfinishedCathedralHasNoEffectiveBuffAndDestroyedCathedralHasNoPayout()throws Exception {try(var db=database()){db.createStatement().execute("UPDATE structure_builds SET status='BUILDING'");assertEquals(0,WonderIncomeStore.pay(db,"day1",0,economy).get(0).coins());db.createStatement().execute("UPDATE structure_builds SET status='WAR_DESTROYED'");assertTrue(WonderIncomeStore.pay(db,"day2",0,economy).isEmpty());}}
    @Test void conquestPenaltyAppliesAfterTaxAndDiscardedIncomeIsAudited()throws Exception {try(var db=database()){db.createStatement().execute("INSERT INTO town_conquests VALUES(1,3)");WonderIncomeStore.pay(db,"day",0,economy,.5);assertEquals(80,value(db,"towns",1,"coins"));assertEquals(40,value(db,"civilizations",1,"coins"));try(var r=db.createStatement().executeQuery("SELECT town_coins,civ_coins,discarded FROM wonder_daily_splits")){r.next();assertEquals(80,r.getLong(1));assertEquals(40,r.getLong(2));assertEquals(80,r.getLong(3));}}}
    @Test void incomeRepaysTownAndCivilizationDebtAndRollbackRestoresBothShares()throws Exception {try(var db=database()){db.createStatement().execute("UPDATE towns SET debt=100 WHERE id=1");db.createStatement().execute("UPDATE civilizations SET debt=30 WHERE id=1");db.setAutoCommit(false);WonderIncomeStore.pay(db,"day",0,economy);assertEquals(60,value(db,"towns",1,"coins"));assertEquals(10,value(db,"civilizations",1,"coins"));db.rollback();assertEquals(100,value(db,"towns",1,"debt"));assertEquals(30,value(db,"civilizations",1,"debt"));assertEquals(1,WonderIncomeStore.pay(db,"day",1,economy).size());db.commit();}}
    @Test void transferredCathedralPaysItsCurrentOwnerUsingTheirTax()throws Exception {try(var db=database()){db.createStatement().execute("UPDATE diplomacy_relations SET status='PEACE'");db.createStatement().execute("UPDATE towns SET civ_id=2 WHERE id=1");var paid=WonderIncomeStore.pay(db,"day",0,economy);assertEquals(2,paid.get(0).civ());assertEquals(280,value(db,"towns",1,"coins"));assertEquals(120,value(db,"civilizations",2,"coins"));assertEquals(0,value(db,"civilizations",1,"coins"));}}
}
